//! Groth16 Phase 2 genesis from a public Phase 1 transcript.
//!
//! A key from [`crate::setup`] is generated by one party that knows every
//! secret. A ceremony instead starts from powers of tau that no single party
//! knows (a snarkjs `.ptau` file from a public Phase 1) and derives the
//! circuit-specific key from them with gamma = delta = 1. Phase 2 then
//! re-randomizes delta.
//!
//! The derivation reproduces `Groth16::generate_parameters_with_qap` with the
//! `LibsnarkReduction`, evaluating at the Phase 1 tau in the exponent rather
//! than at a known scalar:
//!
//! * the Lagrange basis over the arkworks evaluation domain is the inverse FFT
//!   of the first `n` powers, computed here so it cannot disagree with the
//!   domain the prover uses;
//! * `h_query[i] = tau^i * Z(tau) = tau^(i+n) - tau^i`, for `i < n - 1`, which
//!   needs powers up to `tau^(2n-2)`;
//! * public inputs get the extra Lagrange row `num_constraints + i` in A, as in
//!   `instance_map_with_evaluation`.
//!
//! The equivalence is tested against arkworks' own generator below.

use ark_bn254::{Bn254, Fq, Fq2, Fr, G1Affine, G1Projective, G2Affine, G2Projective};
use ark_ec::{pairing::Pairing, AffineRepr, CurveGroup, VariableBaseMSM};
use ark_ff::{BigInt, BigInteger, One, PrimeField, UniformRand};
use ark_groth16::{ProvingKey, VerifyingKey};
use ark_poly::{EvaluationDomain, GeneralEvaluationDomain};
use ark_relations::gr1cs::{ConstraintSystemRef, Matrix, R1CS_PREDICATE_LABEL};
use ark_std::rand::Rng;
use ark_std::{cfg_chunks, cfg_into_iter, cfg_iter, end_timer, start_timer};
use std::io::{Read, Seek, SeekFrom, Write};

#[cfg(feature = "parallel")]
use rayon::prelude::*;

#[derive(Debug)]
pub struct CeremonyError(pub String);

impl std::fmt::Display for CeremonyError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.0)
    }
}

impl std::error::Error for CeremonyError {}

fn err<T>(message: impl Into<String>) -> Result<T, CeremonyError> {
    Err(CeremonyError(message.into()))
}

/// The Phase 1 elements a circuit with a domain of `n` needs.
#[derive(Clone, Debug, PartialEq)]
pub struct Powers {
    /// `tau^i G1` for `i < 2n - 1`.
    pub tau_g1: Vec<G1Affine>,
    /// `tau^i G2` for `i < n`.
    pub tau_g2: Vec<G2Affine>,
    /// `alpha tau^i G1` for `i < n`.
    pub alpha_g1: Vec<G1Affine>,
    /// `beta tau^i G1` for `i < n`.
    pub beta_g1: Vec<G1Affine>,
    pub beta_g2: G2Affine,
}

impl Powers {
    /// Powers for known secrets. Only for tests and disposable development
    /// transcripts: whoever calls this knows the toxic waste.
    pub fn from_secrets(n: usize, tau: Fr, alpha: Fr, beta: Fr) -> Self {
        let mut t = vec![Fr::one(); 2 * n - 1];
        for i in 1..t.len() {
            t[i] = t[i - 1] * tau;
        }
        let g1 = G1Projective::from(G1Affine::generator());
        let g2 = G2Projective::from(G2Affine::generator());
        let times = |base: G1Projective, k: Fr, len: usize| {
            G1Projective::normalize_batch(
                &cfg_iter!(t[..len])
                    .map(|x| base * (*x * k))
                    .collect::<Vec<_>>(),
            )
        };
        Self {
            tau_g1: times(g1, Fr::one(), 2 * n - 1),
            tau_g2: G2Projective::normalize_batch(
                &cfg_iter!(t[..n]).map(|x| g2 * x).collect::<Vec<_>>(),
            ),
            alpha_g1: times(g1, alpha, n),
            beta_g1: times(g1, beta, n),
            beta_g2: (g2 * beta).into_affine(),
        }
    }
}

// snarkjs section ids.
const HEADER: u32 = 1;
const TAU_G1: u32 = 2;
const TAU_G2: u32 = 3;
const ALPHA_G1: u32 = 4;
const BETA_G1: u32 = 5;
const BETA_G2: u32 = 6;

fn u32_le(r: &mut impl Read) -> Result<u32, CeremonyError> {
    let mut b = [0; 4];
    r.read_exact(&mut b)
        .map_err(|e| CeremonyError(e.to_string()))?;
    Ok(u32::from_le_bytes(b))
}

fn u64_le(r: &mut impl Read) -> Result<u64, CeremonyError> {
    let mut b = [0; 8];
    r.read_exact(&mut b)
        .map_err(|e| CeremonyError(e.to_string()))?;
    Ok(u64::from_le_bytes(b))
}

/// snarkjs stores coordinates little-endian in Montgomery form, which is
/// arkworks' internal representation.
fn fq_lem(b: &[u8]) -> Result<Fq, CeremonyError> {
    let mut limbs = [0u64; 4];
    for (limb, chunk) in limbs.iter_mut().zip(b.chunks_exact(8)) {
        *limb = u64::from_le_bytes(chunk.try_into().unwrap());
    }
    let repr = BigInt(limbs);
    if repr >= Fq::MODULUS {
        return err("noncanonical ptau coordinate");
    }
    Ok(Fq::new_unchecked(repr))
}

fn g1_lem(b: &[u8]) -> Result<G1Affine, CeremonyError> {
    if b.iter().all(|x| *x == 0) {
        return Ok(G1Affine::identity());
    }
    let p = G1Affine::new_unchecked(fq_lem(&b[..32])?, fq_lem(&b[32..])?);
    if !p.is_on_curve() {
        return err("ptau G1 point is not on the curve");
    }
    Ok(p)
}

fn g2_lem(b: &[u8]) -> Result<G2Affine, CeremonyError> {
    if b.iter().all(|x| *x == 0) {
        return Ok(G2Affine::identity());
    }
    let p = G2Affine::new_unchecked(
        Fq2::new(fq_lem(&b[..32])?, fq_lem(&b[32..64])?),
        Fq2::new(fq_lem(&b[64..96])?, fq_lem(&b[96..])?),
    );
    if !p.is_on_curve() || !p.is_in_correct_subgroup_assuming_on_curve() {
        return err("ptau G2 point is not in the subgroup");
    }
    Ok(p)
}

fn fq_to_lem(w: &mut impl Write, x: &Fq) -> std::io::Result<()> {
    for limb in x.0 .0 {
        w.write_all(&limb.to_le_bytes())?;
    }
    Ok(())
}

fn g1_to_lem(w: &mut impl Write, p: &G1Affine) -> std::io::Result<()> {
    match p.xy() {
        Some((x, y)) => {
            fq_to_lem(w, &x)?;
            fq_to_lem(w, &y)
        }
        None => w.write_all(&[0; 64]),
    }
}

fn g2_to_lem(w: &mut impl Write, p: &G2Affine) -> std::io::Result<()> {
    match p.xy() {
        Some((x, y)) => {
            for c in [x.c0, x.c1, y.c0, y.c1] {
                fq_to_lem(w, &c)?;
            }
            Ok(())
        }
        None => w.write_all(&[0; 128]),
    }
}

/// The power of a `.ptau` file: it holds `2^(power+1) - 1` G1 powers.
pub fn ptau_power(r: &mut (impl Read + Seek)) -> Result<u32, CeremonyError> {
    Ok(sections(r)?.1)
}

/// Section (id, offset, length) entries and the file's power.
type Sections = (Vec<(u32, u64, u64)>, u32);

fn sections(r: &mut (impl Read + Seek)) -> Result<Sections, CeremonyError> {
    let io = |e: std::io::Error| CeremonyError(e.to_string());
    r.seek(SeekFrom::Start(0)).map_err(io)?;
    let mut magic = [0; 4];
    r.read_exact(&mut magic).map_err(io)?;
    if &magic != b"ptau" {
        return err("not a ptau file");
    }
    let _version = u32_le(r)?;
    let count = u32_le(r)?;
    let mut table = Vec::new();
    for _ in 0..count {
        let id = u32_le(r)?;
        let size = u64_le(r)?;
        let start = r.stream_position().map_err(io)?;
        table.push((id, start, size));
        r.seek(SeekFrom::Current(size as i64)).map_err(io)?;
    }
    let &(_, start, _) = table
        .iter()
        .find(|s| s.0 == HEADER)
        .ok_or(CeremonyError("ptau header missing".into()))?;
    r.seek(SeekFrom::Start(start)).map_err(io)?;
    if u32_le(r)? != 32 {
        return err("ptau is not for a 256-bit base field");
    }
    let mut q = [0; 32];
    r.read_exact(&mut q).map_err(io)?;
    if q.as_slice() != Fq::MODULUS.to_bytes_le() {
        return err("ptau is not for BN254");
    }
    Ok((table, u32_le(r)?))
}

/// Reads the elements a domain of `n` needs from a snarkjs `.ptau` file.
///
/// Every point is checked to be on the curve, and G2 points to be in the
/// subgroup. That says nothing about the powers' structure: see
/// [`check_powers`].
pub fn read_ptau(r: &mut (impl Read + Seek), n: usize) -> Result<Powers, CeremonyError> {
    let io = |e: std::io::Error| CeremonyError(e.to_string());
    let (table, power) = sections(r)?;
    if (1usize << power) < n {
        return err(format!("ptau power {power} is below the domain size {n}"));
    }
    let mut section = |id: u32, size: usize, count: usize| -> Result<Vec<u8>, CeremonyError> {
        let &(_, start, len) = table
            .iter()
            .find(|s| s.0 == id)
            .ok_or(CeremonyError(format!("ptau section {id} missing")))?;
        if ((size * count) as u64) > len {
            return err(format!("ptau section {id} is too short"));
        }
        r.seek(SeekFrom::Start(start)).map_err(io)?;
        let mut bytes = vec![0; size * count];
        r.read_exact(&mut bytes).map_err(io)?;
        Ok(bytes)
    };
    let g1s = |bytes: Vec<u8>| -> Result<Vec<G1Affine>, CeremonyError> {
        cfg_chunks!(bytes, 64).map(g1_lem).collect()
    };
    let tau_g1 = g1s(section(TAU_G1, 64, 2 * n - 1)?)?;
    let alpha_g1 = g1s(section(ALPHA_G1, 64, n)?)?;
    let beta_g1 = g1s(section(BETA_G1, 64, n)?)?;
    let g2_bytes = section(TAU_G2, 128, n)?;
    let tau_g2 = cfg_chunks!(g2_bytes, 128)
        .map(g2_lem)
        .collect::<Result<Vec<_>, _>>()?;
    let beta_g2 = g2_lem(&section(BETA_G2, 128, 1)?)?;
    Ok(Powers {
        tau_g1,
        tau_g2,
        alpha_g1,
        beta_g1,
        beta_g2,
    })
}

/// Writes `powers` as a minimal snarkjs `.ptau` (header and sections 2-6).
///
/// Used for disposable development transcripts; a real ceremony reads a
/// published file instead.
pub fn write_ptau(w: &mut impl Write, powers: &Powers, power: u32) -> std::io::Result<()> {
    assert_eq!(powers.tau_g1.len(), (2usize << power) - 1);
    w.write_all(b"ptau")?;
    w.write_all(&1u32.to_le_bytes())?;
    w.write_all(&6u32.to_le_bytes())?;
    let mut header = Vec::new();
    header.extend_from_slice(&32u32.to_le_bytes());
    header.extend_from_slice(&Fq::MODULUS.to_bytes_le());
    header.extend_from_slice(&power.to_le_bytes());
    header.extend_from_slice(&power.to_le_bytes());
    let mut section = |id: u32, bytes: Vec<u8>| -> std::io::Result<()> {
        w.write_all(&id.to_le_bytes())?;
        w.write_all(&(bytes.len() as u64).to_le_bytes())?;
        w.write_all(&bytes)
    };
    section(HEADER, header)?;
    let g1s = |points: &[G1Affine]| -> std::io::Result<Vec<u8>> {
        let mut bytes = Vec::with_capacity(points.len() * 64);
        for p in points {
            g1_to_lem(&mut bytes, p)?;
        }
        Ok(bytes)
    };
    section(TAU_G1, g1s(&powers.tau_g1)?)?;
    let mut g2s = Vec::with_capacity(powers.tau_g2.len() * 128);
    for p in &powers.tau_g2 {
        g2_to_lem(&mut g2s, p)?;
    }
    section(TAU_G2, g2s)?;
    section(ALPHA_G1, g1s(&powers.alpha_g1)?)?;
    section(BETA_G1, g1s(&powers.beta_g1)?)?;
    let mut beta = Vec::with_capacity(128);
    g2_to_lem(&mut beta, &powers.beta_g2)?;
    section(BETA_G2, beta)
}

fn combine<G: VariableBaseMSM<ScalarField = Fr>>(points: &[G::MulBase], scalars: &[Fr]) -> G {
    G::msm_unchecked(points, scalars)
}

/// Checks that `powers` is a consistent powers-of-tau structure, by random
/// linear combinations of the pairing relations.
///
/// This shows the elements share one tau, alpha and beta with nontrivial
/// values. It does not show that nobody knows them: that is what the published
/// Phase 1 transcript and its hash attest.
pub fn check_powers<R: Rng>(powers: &Powers, rng: &mut R) -> Result<(), CeremonyError> {
    let Powers {
        tau_g1,
        tau_g2,
        alpha_g1,
        beta_g1,
        beta_g2,
    } = powers;
    let n = tau_g2.len();
    if tau_g1.len() != 2 * n - 1 || alpha_g1.len() != n || beta_g1.len() != n || n < 2 {
        return err("inconsistent power counts");
    }
    let (g1, g2) = (G1Affine::generator(), G2Affine::generator());
    if tau_g1[0] != g1 || tau_g2[0] != g2 {
        return err("powers do not start at the generators");
    }
    if tau_g1[1] == g1 || tau_g1[1].is_zero() || alpha_g1[0].is_zero() || beta_g1[0].is_zero() {
        return err("degenerate tau, alpha or beta");
    }
    let r: Vec<Fr> = (0..tau_g1.len()).map(|_| Fr::rand(rng)).collect();
    let pair = |a: G1Projective, b: G2Projective| Bn254::pairing(a, b);
    let m = tau_g1.len() - 1;
    if pair(
        combine::<G1Projective>(&tau_g1[..m], &r[..m]),
        tau_g2[1].into(),
    ) != pair(combine::<G1Projective>(&tau_g1[1..], &r[..m]), g2.into())
    {
        return err("tau G1 powers are inconsistent");
    }
    if pair(
        tau_g1[1].into(),
        combine::<G2Projective>(&tau_g2[..n - 1], &r[..n - 1]),
    ) != pair(
        g1.into(),
        combine::<G2Projective>(&tau_g2[1..], &r[..n - 1]),
    ) {
        return err("tau G2 powers are inconsistent");
    }
    let tau_combined = combine::<G2Projective>(tau_g2, &r[..n]);
    for (name, points) in [("alpha", alpha_g1), ("beta", beta_g1)] {
        if pair(combine::<G1Projective>(points, &r[..n]), g2.into())
            != pair(points[0].into(), tau_combined)
        {
            return err(format!("{name} G1 powers are inconsistent"));
        }
    }
    if pair(beta_g1[0].into(), g2.into()) != pair(g1.into(), (*beta_g2).into()) {
        return err("beta G2 is inconsistent");
    }
    Ok(())
}

/// The R1CS matrices of a finalized setup-mode constraint system.
pub struct R1cs {
    pub num_instance: usize,
    pub num_witness: usize,
    pub num_constraints: usize,
    pub matrices: Vec<Matrix<Fr>>,
}

impl R1cs {
    pub fn from_cs(cs: &ConstraintSystemRef<Fr>) -> Result<Self, CeremonyError> {
        let mut matrices = cs
            .to_matrices()
            .map_err(|e| CeremonyError(e.to_string()))?
            .remove(R1CS_PREDICATE_LABEL)
            .ok_or(CeremonyError("no R1CS predicate".into()))?;
        if matrices.len() != 3 {
            return err("expected A, B and C matrices");
        }
        matrices.iter_mut().for_each(|m| m.shrink_to_fit());
        Ok(Self {
            num_instance: cs.num_instance_variables(),
            num_witness: cs.num_witness_variables(),
            num_constraints: cs.num_constraints(),
            matrices,
        })
    }

    pub fn domain(&self) -> Result<GeneralEvaluationDomain<Fr>, CeremonyError> {
        GeneralEvaluationDomain::new(self.num_constraints + self.num_instance)
            .ok_or(CeremonyError("domain too large".into()))
    }

    pub fn domain_size(&self) -> usize {
        self.domain().map_or(0, |d| d.size())
    }

    /// Keccak-256 over the counts and every matrix entry, in synthesis order.
    ///
    /// Two builds share a digest if and only if they synthesize the same
    /// constraint system, so a published digest pins the circuit version a
    /// ceremony key belongs to.
    pub fn digest(&self) -> [u8; 32] {
        use tiny_keccak::{Hasher, Keccak};
        let mut h = Keccak::v256();
        h.update(b"mirage-r1cs-v1");
        for x in [self.num_instance, self.num_witness, self.num_constraints] {
            h.update(&(x as u64).to_le_bytes());
        }
        for matrix in &self.matrices {
            for row in matrix {
                h.update(&(row.len() as u64).to_le_bytes());
                for (coeff, index) in row {
                    h.update(&(*index as u64).to_le_bytes());
                    h.update(&coeff.into_bigint().to_bytes_le());
                }
            }
        }
        let mut out = [0; 32];
        h.finalize(&mut out);
        out
    }
}

/// One variable's terms: (constraint row, coefficient).
type Column = Vec<(u32, Fr)>;

/// Columns with at least this many terms are summed by one parallel MSM.
const MSM_MIN_TERMS: usize = 1 << 10;

/// For each variable `j`, `extra[j]` (when present) plus the sum over `parts`
/// of `coeff * bases[row]` for every term in that part's column `j`.
///
/// Short columns are summed term by term, in parallel across variables. Long
/// ones (the constant one appears in over a million constraints) would be a
/// serial tail there, so each is one parallel MSM instead, run outside the
/// variable loop: nesting it inside overflows rayon worker stacks.
fn query<G>(
    parts: &[(&[G::Affine], &[Column])],
    extra: &[G::Affine],
    num_vars: usize,
    msm_min: usize,
) -> Vec<G>
where
    G: CurveGroup<ScalarField = Fr> + VariableBaseMSM<MulBase = <G as CurveGroup>::Affine>,
{
    let long = |j: usize| parts.iter().map(|(_, cols)| cols[j].len()).sum::<usize>() >= msm_min;
    let sum = |j: usize| {
        let msm = long(j);
        let mut acc = extra.get(j).map_or(G::zero(), |p| (*p).into());
        let (mut bases, mut scalars) = (Vec::new(), Vec::new());
        for (points, columns) in parts {
            for (k, coeff) in &columns[j] {
                let base = points[*k as usize];
                if coeff.is_one() {
                    acc += base;
                } else if (-*coeff).is_one() {
                    acc -= base;
                } else if msm {
                    bases.push(base);
                    scalars.push(*coeff);
                } else {
                    acc += base * coeff;
                }
            }
        }
        if !bases.is_empty() {
            acc += G::msm_unchecked(&bases, &scalars);
        }
        acc
    };
    let mut out: Vec<G> = cfg_into_iter!(0..num_vars)
        .map(|j| if long(j) { G::zero() } else { sum(j) })
        .collect();
    for j in (0..num_vars).filter(|j| long(*j)) {
        out[j] = sum(j);
    }
    out
}

/// The genesis proving key for `r1cs` from Phase 1 `powers`, with
/// gamma = delta = 1.
pub fn genesis(r1cs: &R1cs, powers: &Powers) -> Result<ProvingKey<Bn254>, CeremonyError> {
    let domain = r1cs.domain()?;
    let n = domain.size();
    if powers.tau_g2.len() < n || powers.tau_g1.len() < 2 * n - 1 {
        return err("not enough powers for the domain");
    }
    let timer = start_timer!(|| "Lagrange basis");
    let lagrange_g1 = |points: &[G1Affine]| {
        let mut v: Vec<G1Projective> = cfg_iter!(points[..n]).map(|p| (*p).into()).collect();
        domain.ifft_in_place(&mut v);
        G1Projective::normalize_batch(&v)
    };
    let lt = lagrange_g1(&powers.tau_g1);
    let la = lagrange_g1(&powers.alpha_g1);
    let lb = lagrange_g1(&powers.beta_g1);
    let mut lt2: Vec<G2Projective> = cfg_iter!(powers.tau_g2[..n]).map(|p| (*p).into()).collect();
    domain.ifft_in_place(&mut lt2);
    let lt2 = G2Projective::normalize_batch(&lt2);
    end_timer!(timer);

    let (ni, nc) = (r1cs.num_instance, r1cs.num_constraints);
    let num_vars = ni + r1cs.num_witness;
    let columns = |matrix: &Matrix<Fr>| {
        let mut cols: Vec<Column> = vec![Vec::new(); num_vars];
        for (k, row) in matrix.iter().enumerate() {
            for (coeff, index) in row {
                cols[*index].push((k as u32, *coeff));
            }
        }
        cols
    };
    let [a, b, c] = [0, 1, 2].map(|i| columns(&r1cs.matrices[i]));

    // Public inputs also take the Lagrange rows after the constraints, in A.
    let timer = start_timer!(|| "A query");
    let a_query: Vec<G1Projective> = query(&[(&lt, &a)], &lt[nc..nc + ni], num_vars, MSM_MIN_TERMS);
    end_timer!(timer);
    let timer = start_timer!(|| "B G1 query");
    let b_g1_query: Vec<G1Projective> = query(&[(&lt, &b)], &[], num_vars, MSM_MIN_TERMS);
    end_timer!(timer);
    let timer = start_timer!(|| "B G2 query");
    let b_g2_query: Vec<G2Projective> = query(&[(&lt2, &b)], &[], num_vars, MSM_MIN_TERMS);
    end_timer!(timer);
    let timer = start_timer!(|| "L query");
    // beta * A + alpha * B + C, over gamma (instance) or delta (witness).
    let abc: Vec<G1Projective> = query(
        &[(&lb, &a), (&la, &b), (&lt, &c)],
        &lb[nc..nc + ni],
        num_vars,
        MSM_MIN_TERMS,
    );
    end_timer!(timer);
    let h_query: Vec<G1Projective> = cfg_into_iter!(0..n - 1)
        .map(|i| G1Projective::from(powers.tau_g1[i + n]) - powers.tau_g1[i])
        .collect();

    let abc = G1Projective::normalize_batch(&abc);
    let (g1, g2) = (G1Affine::generator(), G2Affine::generator());
    Ok(ProvingKey {
        vk: VerifyingKey {
            alpha_g1: powers.alpha_g1[0],
            beta_g2: powers.beta_g2,
            gamma_g2: g2,
            delta_g2: g2,
            gamma_abc_g1: abc[..ni].to_vec(),
        },
        beta_g1: powers.beta_g1[0],
        delta_g1: g1,
        a_query: G1Projective::normalize_batch(&a_query),
        b_g1_query: G1Projective::normalize_batch(&b_g1_query),
        b_g2_query: G2Projective::normalize_batch(&b_g2_query),
        h_query: G1Projective::normalize_batch(&h_query),
        l_query: abc[ni..].to_vec(),
    })
}

#[cfg(test)]
mod tests {
    use super::*;
    use ark_ff::Zero;
    use ark_groth16::Groth16;
    use ark_relations::gr1cs::{
        ConstraintSynthesizer, ConstraintSystem, LinearCombination, OptimizationGoal,
        SynthesisError, SynthesisMode, Variable,
    };
    use ark_snark::SNARK;
    use ark_std::rand::{rngs::StdRng, SeedableRng};

    /// x^3 + x + 5 = y with y public, plus a second public input and repeated,
    /// scaled and negated terms so every query and coefficient path is used.
    #[derive(Clone)]
    struct Cubic(Option<Fr>);

    impl ConstraintSynthesizer<Fr> for Cubic {
        fn generate_constraints(self, cs: ConstraintSystemRef<Fr>) -> Result<(), SynthesisError> {
            let x_val = self.0;
            let x = cs.new_witness_variable(|| x_val.ok_or(SynthesisError::AssignmentMissing))?;
            let x2 = cs.new_witness_variable(|| {
                x_val
                    .map(|x| x * x)
                    .ok_or(SynthesisError::AssignmentMissing)
            })?;
            let x3 = cs.new_witness_variable(|| {
                x_val
                    .map(|x| x * x * x)
                    .ok_or(SynthesisError::AssignmentMissing)
            })?;
            let y = cs.new_input_variable(|| {
                x_val
                    .map(|x| x * x * x + x + Fr::from(5u64))
                    .ok_or(SynthesisError::AssignmentMissing)
            })?;
            let z = cs.new_input_variable(|| {
                x_val.map(|x| -x).ok_or(SynthesisError::AssignmentMissing)
            })?;
            cs.enforce_r1cs_constraint(|| x.into(), || x.into(), || x2.into())?;
            cs.enforce_r1cs_constraint(|| x2.into(), || x.into(), || x3.into())?;
            cs.enforce_r1cs_constraint(
                || LinearCombination::from(x3) + x + (Fr::from(5u64), Variable::One),
                || Variable::One.into(),
                || y.into(),
            )?;
            cs.enforce_r1cs_constraint(
                || LinearCombination::from(x) * Fr::from(3u64),
                || LinearCombination::from(z) * -Fr::one(),
                || LinearCombination::from(x2) * Fr::from(3u64),
            )?;
            // Enough scaled terms on x and the constant to take the MSM path.
            for k in [11u64, 13, 17, 19] {
                let lc =
                    || LinearCombination::from(x) * Fr::from(k) + (Fr::from(k + 1), Variable::One);
                cs.enforce_r1cs_constraint(
                    lc,
                    || (Fr::from(k), Variable::One).into(),
                    || lc() * Fr::from(k),
                )?;
            }
            Ok(())
        }
    }

    fn r1cs(circuit: Cubic) -> R1cs {
        let cs = ConstraintSystem::new_ref();
        cs.set_optimization_goal(OptimizationGoal::Constraints);
        cs.set_mode(SynthesisMode::Setup);
        circuit.generate_constraints(cs.clone()).unwrap();
        cs.finalize();
        R1cs::from_cs(&cs).unwrap()
    }

    #[test]
    fn genesis_matches_arkworks_generator() {
        let mut rng = StdRng::seed_from_u64(7);
        let (alpha, beta) = (Fr::rand(&mut rng), Fr::rand(&mut rng));
        // The generator draws only tau from its rng, so a clone predicts it.
        let tau = Fr::rand(&mut rng.clone());
        let expected = Groth16::<Bn254>::generate_parameters_with_qap(
            Cubic(None),
            alpha,
            beta,
            Fr::one(),
            Fr::one(),
            G1Affine::generator().into(),
            G2Affine::generator().into(),
            &mut rng,
        )
        .unwrap();
        let r1cs = r1cs(Cubic(None));
        let n = r1cs.domain().unwrap().size();
        let powers = Powers::from_secrets(n, tau, alpha, beta);
        check_powers(&powers, &mut rng).unwrap();
        let pk = genesis(&r1cs, &powers).unwrap();
        assert_eq!(pk, expected);

        let proof = Groth16::<Bn254>::prove(&pk, Cubic(Some(Fr::from(3u64))), &mut rng).unwrap();
        let inputs = [Fr::from(35u64), -Fr::from(3u64)];
        assert!(Groth16::<Bn254>::verify(&pk.vk, &inputs, &proof).unwrap());
        assert!(!Groth16::<Bn254>::verify(&pk.vk, &[inputs[1], inputs[0]], &proof).unwrap());
    }

    #[test]
    fn ptau_round_trip_and_tamper() {
        let mut rng = StdRng::seed_from_u64(9);
        let power = 3;
        let powers = Powers::from_secrets(
            1 << power,
            Fr::rand(&mut rng),
            Fr::rand(&mut rng),
            Fr::rand(&mut rng),
        );
        let mut file = Vec::new();
        write_ptau(&mut file, &powers, power).unwrap();
        let mut cursor = std::io::Cursor::new(&file);
        assert_eq!(ptau_power(&mut cursor).unwrap(), power);
        assert_eq!(read_ptau(&mut cursor, 1 << power).unwrap(), powers);
        assert!(read_ptau(&mut cursor, 1 << (power + 1)).is_err());

        let mut swapped = powers.clone();
        swapped.tau_g1.swap(3, 4);
        assert!(check_powers(&swapped, &mut rng).is_err());
        let mut shifted = powers.clone();
        shifted.alpha_g1[2] = powers.beta_g1[2];
        assert!(check_powers(&shifted, &mut rng).is_err());
        let mut g2 = powers.clone();
        g2.tau_g2[5] = g2.tau_g2[4];
        assert!(check_powers(&g2, &mut rng).is_err());
        let mut beta = powers;
        beta.beta_g2 = beta.tau_g2[1];
        assert!(check_powers(&beta, &mut rng).is_err());
    }

    #[test]
    fn query_paths_agree() {
        let mut rng = StdRng::seed_from_u64(11);
        let g1: Vec<G1Affine> = (0..64).map(|_| G1Affine::rand(&mut rng)).collect();
        let h1: Vec<G1Affine> = (0..64).map(|_| G1Affine::rand(&mut rng)).collect();
        let g2: Vec<G2Affine> = (0..64).map(|_| G2Affine::rand(&mut rng)).collect();
        let column = |rng: &mut StdRng| -> Column {
            (0..rng.gen_range(0..40))
                .map(|_| {
                    let coeff = match rng.gen_range(0..3) {
                        0 => Fr::one(),
                        1 => -Fr::one(),
                        _ => Fr::rand(rng),
                    };
                    (rng.gen_range(0..64), coeff)
                })
                .collect()
        };
        let a: Vec<Column> = (0..50).map(|_| column(&mut rng)).collect();
        let b: Vec<Column> = (0..50).map(|_| column(&mut rng)).collect();
        let parts: [(&[G1Affine], &[Column]); 2] = [(&g1, &a), (&h1, &b)];
        let msm: Vec<G1Projective> = query(&parts, &g1[..3], 50, 1);
        assert_eq!(msm, query::<G1Projective>(&parts, &g1[..3], 50, usize::MAX));
        assert!(msm.iter().any(|p| !p.is_zero()));
        let msm: Vec<G2Projective> = query(&[(&g2, &a)], &[], 50, 1);
        assert_eq!(
            msm,
            query::<G2Projective>(&[(&g2, &a)], &[], 50, usize::MAX)
        );
    }

    #[test]
    fn digest_tracks_the_circuit() {
        let a = r1cs(Cubic(None));
        assert_eq!(a.digest(), r1cs(Cubic(None)).digest());
        let mut b = r1cs(Cubic(None));
        b.matrices[2][0][0].0 += Fr::one();
        assert_ne!(a.digest(), b.digest());
    }

    /// Reads a published Hermez file, e.g. powersOfTau28_hez_final_08.ptau.
    #[test]
    #[ignore]
    fn published_ptau() {
        let path = std::env::var("MIRAGE_PTAU").expect("MIRAGE_PTAU");
        let mut file = std::io::BufReader::new(std::fs::File::open(path).unwrap());
        let n = 1 << ptau_power(&mut file).unwrap();
        let powers = read_ptau(&mut file, n).unwrap();
        check_powers(&powers, &mut StdRng::seed_from_u64(1)).unwrap();
    }
}
